def main():
    target = ROOT / "data/citylearn2022"
    target.mkdir(parents=True, exist_ok=True)
    for item in SOURCE["files"]:
        path = target / item["file"]
        data = path.read_bytes() if path.exists() else urlopen(item["url"], timeout=60).read()
        if hashlib.sha256(data).hexdigest() != item["sha256"]:
            raise ValueError("Source hash mismatch: " + item["file"])
        if not path.exists():
            path.write_bytes(data)
        print("Verified " + item["file"])
    (target / "manifest.json").write_text(json.dumps(SOURCE, indent=2), encoding="utf-8")
    for folder in ("results", "outputs/tables", "outputs/figures"):
        (ROOT / folder).mkdir(parents=True, exist_ok=True)

if __name__ == "__main__":
    main()
